{
  "paper": {
    "contribution": "Re:CAP proposes an out-of-band, iterative topic-probing audit for surfacing retrieval gaps in deployed RAG without per-query gold labels (pp. 2–3).",
    "key_claims": [
      {
        "claim": "On bounded-evidence benchmarks, Re:CAP improves recall over flat retrieval at matched document budgets, with the reported MuSiQue gain over hybrid top-500 at +12.9 percentage points.",
        "evidence_refs": [
          {
            "page": 5,
            "section": "4.1 Re:CAP vs. flat retrieval",
            "quote": "on MuSiQue, +12.9 pp vs. flat MiniLM hybrid top-500"
          }
        ]
      },
      {
        "claim": "On TREC-COVID, 21.2% of Re:CAP-recovered gold remains absent from the combined top-500 outputs of BM25, dense, and hybrid retrieval.",
        "evidence_refs": [
          {
            "page": 5,
            "section": "4.1 Re:CAP vs. flat retrieval",
            "quote": "21.2% remains absent from the ensemble of flat BM25, dense, and hybrid top-500"
          }
        ]
      },
      {
        "claim": "Across three MuSiQue runs, Re:CAP recall has 0.47% coefficient of variation; this is benchmark stability evidence, not production variance evidence.",
        "evidence_refs": [
          {
            "page": 7,
            "section": "Table 5",
            "quote": "Re:CAP recall 0.8972 0.0043 0.47%"
          }
        ]
      }
    ],
    "evidence": [
      {
        "claim": "The proposed audit extracts covered topics, probes for missing facets, retrieves candidates, and judges novelty.",
        "evidence_refs": [
          {
            "page": 2,
            "section": "Introduction",
            "quote": "generates entity-anchored gap-probing questions targeting aspects relevant to Q but absent from T"
          }
        ]
      },
      {
        "claim": "Human annotators rated 78.9% of sampled ensemble-unreachable benchmark documents as adding information beyond the baseline answer.",
        "evidence_refs": [
          {
            "page": 7,
            "section": "5 Human evaluation",
            "quote": "78.9% [71.5–86.2%] of ensemble-missed gap documents are judged new_info"
          }
        ]
      },
      {
        "claim": "Human annotators rated 73.9% of sampled judge-identified production gap documents as adding information; these audits lack production gold labels.",
        "evidence_refs": [
          {
            "page": 16,
            "section": "F Human Evaluation on the Production Cohorts",
            "quote": "73.9% overall"
          }
        ]
      }
    ],
    "limitations": [
      "The audit cannot discover topics absent from the corpus, so it measures retrieval gaps rather than corpus gaps (p. 8).",
      "The authors report that 95.3% of missing-gold losses on bounded-evidence benchmarks never reach the candidate pool, implicating upstream probing coverage (p. 23).",
      "Production results have no calibrated recall or variance estimates because production gold labels are unavailable and each cohort was run once (p. 16).",
      "The default audit costs $0.59–$2.05 per query and uses 250–500 LLM calls, limiting suitability for tight monitoring budgets (pp. 8–9)."
    ]
  },
  "insights": [
    {
      "insight": "Treat retrieval coverage as an independently auditable failure surface: answer-side faithfulness can coexist with omitted corpus evidence.",
      "why_it_matters": "Agent reliability evaluations that inspect only generated answers can miss retrieval omissions; this paper proposes an out-of-band audit, not an inline agent monitor.",
      "evidence_refs": [
        {
          "page": 1,
          "section": "1 Introduction",
          "quote": "an answer that is fluent and faithful to its retrieved context can still be substantively incomplete"
        }
      ],
      "confidence": 0.9,
      "novelty": "Relevant reframing for evaluation and assurance; the paper positions this as complementary to existing RAG metrics, not as a claim of novelty relative to agent evaluations.",
      "related_rmax_topics": [
        "evaluation/assurance",
        "agent reliability"
      ],
      "possible_action": "Add sampled retrieval-coverage audits alongside answer-quality metrics when assessing knowledge-agent changes."
    },
    {
      "insight": "A high gap-discovery signal is not a calibrated reliability score: benchmarks support recall and run stability, while production evidence is human-judged and single-snapshot.",
      "why_it_matters": "Governance dashboards should distinguish measured benchmark performance from uncalibrated production indicators and avoid treating gap rate as proof of completeness.",
      "evidence_refs": [
        {
          "page": 16,
          "section": "Scope of these case studies",
          "quote": "They do not provide calibrated recall numbers (no production gold labels) or variance estimates (single run per cohort)."
        }
      ],
      "confidence": 0.96,
      "novelty": "Evidence-bound assurance implication; no claim that this monitoring pattern is novel.",
      "related_rmax_topics": [
        "evaluation/assurance",
        "MCP/governance"
      ],
      "possible_action": "Label production gap-rate metrics as uncalibrated, and periodically validate judge outputs with human or held-out-qrel checks."
    },
    {
      "insight": "The harness must account for probe-generation and judge failure separately: the reported bounded-evidence losses are mostly failures to surface candidates, not failures to judge them.",
      "why_it_matters": "Improving judge accuracy alone may leave the dominant retrieval-audit failure mode unchanged; the paper’s measured attribution is specific to its benchmark setup.",
      "evidence_refs": [
        {
          "page": 23,
          "section": "O Failure-Mode Analysis",
          "quote": "dominant failure modes are early convergence (41/43), gap-Q off-topic from bridge-entity erasure (19/43)"
        },
        {
          "page": 23,
          "section": "Table 23",
          "quote": "AND only 43 64 4.7% 95.3%"
        }
      ],
      "confidence": 0.86,
      "novelty": "A measured diagnostic for this audit harness; it does not establish the same failure distribution for other agents or tools.",
      "related_rmax_topics": [
        "harness/runtime",
        "tool use",
        "long-running workflows"
      ],
      "possible_action": "Instrument candidate-generation yield and early-convergence reasons separately from judge rejection in evaluation runs."
    }
  ],
